// ====== EDIT THIS BLOCK ======
const CONFIG = {
  siteUrl: 'sc-domain:yourdomain.com',        // Domain property: 'sc-domain:x.com' | URL-prefix: 'https://www.x.com/'
  reportEmail: 'your-email@example.com',// comma separate for multiple
  lagDays: 3,                                 // GSC data lags ~2-3 days
  periodDays: 7,                              // current / previous window length
  minImpressions: 5,                          // ignore queries/pages below this (noise filter)
  rankingChangeThreshold: 2,                  // positions moved to count as improved / declined
  positionNoiseMax: 30,                       // if BOTH weeks are deeper than this, ignore the movement
  ctrMaxPosition: 10,                         // "CTR below expected" check only for positions <= this
  ctrMinExpectedClicks: 2,                    // ...and only if the benchmark predicts at least this many clicks
  rankingOpportunityMin: 4,                   // striking distance range
  rankingOpportunityMax: 30,
  opportunityMinImpressions: 5,
  targetPosition: 3,                          // upside is estimated for reaching this position
  lowDataClicks: 30,                          // below this many clicks (cur+prev) show absolute change instead of %
  brandTerms: ['yourbrand', 'brandname'],       // queries containing these are "brand"
  commercialTerms: ['service', 'services', 'pricing', 'price', 'cost', 'consulting', 'consultant', 'consultants', 'company', 'companies', 'agency', 'hire', 'vendor', 'vendors', 'provider', 'providers', 'solution', 'solutions', 'case study', 'case studies', 'partner', 'outsourcing', 'quote', 'demo', 'implementation'],
  informationalTerms: ['what', 'how', 'why', 'when', 'guide', 'tutorial', 'vs', 'versus', 'difference', 'example', 'examples', 'use case', 'use cases', 'best practices', 'benefits', 'explained', 'definition', 'overview', 'introduction', 'comparison', 'learn'],
  topics: {},                                 // optional manual topics, e.g. { 'Agentic SDLC': ['agentic','sdlc'], 'Polars / DataFusion': ['polars','datafusion'] }. Empty = automatic.
  sectionDepth: 2,                            // URL segments used to group pages: /resources/blogs/x -> /resources/blogs
  cannibalMinImpressions: 3,                  // a page must have this many impressions for a query to count in cannibalization
  targetCountries: [],                        // e.g. ['IND','USA'] (ISO-3 codes). Empty = skip target-market share
  ctrCurve: { '1': 0.28, '2': 0.15, '3': 0.10, '4': 0.07, '5': 0.05, '6': 0.04, '7': 0.03, '8': 0.025, '9': 0.02, '10': 0.018, 'p11_20': 0.01, 'p21plus': 0.003 }, // generic benchmark CTR by position; replace with your own once you have history
  topN: 10                                    // rows per section
};
// ====== DON'T EDIT BELOW ======
const fmt = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; };
const curEnd = addDays(new Date(), -CONFIG.lagDays);
const curStart = addDays(curEnd, -(CONFIG.periodDays - 1));
const prevEnd = addDays(curStart, -1);
const prevStart = addDays(prevEnd, -(CONFIG.periodDays - 1));
return [{ json: { ...CONFIG, curStart: fmt(curStart), curEnd: fmt(curEnd), prevStart: fmt(prevStart), prevEnd: fmt(prevEnd) } }];

const cfg = $('Config').first().json;
const thr = cfg.rankingChangeThreshold;
const N = cfg.topN;

const rowsOf = (name) => $(name).all().flatMap((i) => (i.json && Array.isArray(i.json.rows) ? i.json.rows : []));
const pct = (c, p) => (p > 0 ? ((c - p) / p) * 100 : null);
const n0 = (x) => Math.round(Number(x) || 0).toLocaleString('en-US');
const f1 = (x) => Number(x).toFixed(1);
const norm = (q) => ' ' + String(q).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim() + ' ';
const sum = (arr, k) => arr.reduce((s, e) => s + (e[k] || 0), 0);
const wpos = (arr, pk, wk) => { let s = 0, w = 0; for (const e of arr) if (e[pk] !== null && e[pk] !== undefined && e[wk] > 0) { s += e[pk] * e[wk]; w += e[wk]; } return w ? s / w : null; };

// ---------- Overall KPIs ----------
const total = (name) => {
  const r = rowsOf(name)[0];
  return r ? { clicks: r.clicks, impressions: r.impressions, ctr: r.ctr, position: r.position }
           : { clicks: 0, impressions: 0, ctr: 0, position: 0 };
};
const tc = total('GSC Totals Current');
const tp = total('GSC Totals Previous');
const lowVol = tc.clicks + tp.clicks < cfg.lowDataClicks;
const kpi = {
  lowVol,
  clicks: { cur: tc.clicks, prev: tp.clicks, pct: pct(tc.clicks, tp.clicks) },
  impressions: { cur: tc.impressions, prev: tp.impressions, pct: pct(tc.impressions, tp.impressions) },
  ctr: { cur: tc.ctr, prev: tp.ctr, diff: (tc.ctr - tp.ctr) * 100 },
  position: { cur: tc.position, prev: tp.position, delta: tp.position - tc.position }
};

// ---------- Helpers: brand, intent, CTR benchmark ----------
const brandTerms = (cfg.brandTerms || []).map((t) => t.toLowerCase());
const isBrand = (q) => { const s = String(q).toLowerCase(); return brandTerms.some((t) => s.includes(t)); };
const hasTerm = (s, list) => (list || []).some((t) => s.includes(' ' + t.toLowerCase() + ' '));
const intentOf = (q) => {
  if (isBrand(q)) return 'Brand';
  const s = norm(q);
  if (hasTerm(s, cfg.commercialTerms)) return 'Commercial';
  if (hasTerm(s, cfg.informationalTerms)) return 'Informational';
  return 'Other / topic';
};
const ctrAt = (pos) => {
  const c = cfg.ctrCurve; const r = Math.round(pos);
  if (r <= 1) return c['1'];
  if (r <= 10) return c[String(r)];
  return r <= 20 ? c.p11_20 : c.p21plus;
};

// ---------- Compare current vs previous per query / page ----------
const blank = (key) => ({ key, c: 0, i: 0, ctr: 0, pos: null, pc: 0, pi: 0, pctr: 0, ppos: null });

function compare(curRows, prevRows) {
  const m = new Map();
  for (const r of prevRows) {
    const e = blank(r.keys[0]);
    e.pc = r.clicks; e.pi = r.impressions; e.pctr = r.ctr; e.ppos = r.position;
    m.set(e.key, e);
  }
  for (const r of curRows) {
    const e = m.get(r.keys[0]) || blank(r.keys[0]);
    e.c = r.clicks; e.i = r.impressions; e.ctr = r.ctr; e.pos = r.position;
    m.set(e.key, e);
  }
  const out = [];
  for (const e of m.values()) {
    e.posDelta = e.pos !== null && e.ppos !== null ? e.ppos - e.pos : null; // + = improved
    e.clickDiff = e.c - e.pc;
    e.clickPct = pct(e.c, e.pc);
    e.impPct = pct(e.i, e.pi);
    e.exp = e.pos !== null ? e.i * ctrAt(e.pos) : 0; // benchmark clicks
    let status = 'IGNORED';
    if (e.pi === 0 && e.i >= cfg.minImpressions) status = 'NEW';
    else if (e.i === 0 && e.pi >= cfg.minImpressions) status = 'LOST';
    else if (e.i >= cfg.minImpressions && e.pi >= cfg.minImpressions && e.posDelta !== null) {
      if (Math.min(e.pos, e.ppos) > cfg.positionNoiseMax) status = 'IGNORED'; // both weeks deep = noise
      else status = e.posDelta >= thr ? 'IMPROVED' : e.posDelta <= -thr ? 'DECLINED' : 'STABLE';
    }
    e.status = status;
    out.push(e);
  }
  return out;
}

const queries = compare(rowsOf('GSC Queries Current'), rowsOf('GSC Queries Previous'));
const pages = compare(rowsOf('GSC Pages Current'), rowsOf('GSC Pages Previous'));

const count = (arr) => {
  const o = { IMPROVED: 0, STABLE: 0, DECLINED: 0, NEW: 0, LOST: 0 };
  for (const e of arr) if (o[e.status] !== undefined) o[e.status]++;
  return o;
};
const counts = { queries: count(queries), pages: count(pages) };

// ---------- Query -> page mapping ----------
const qpMap = new Map();
for (const r of rowsOf('GSC QueryPage Current')) {
  const q = r.keys[0], p = r.keys[1];
  if (!qpMap.has(q)) qpMap.set(q, []);
  qpMap.get(q).push({ page: p, i: r.impressions, c: r.clicks, pos: r.position });
}
const pathOf = (u) => String(u).replace(/^https?:\/\/[^/]+/, '').split('?')[0].split('#')[0] || '/';
const primaryPage = (q) => { const a = qpMap.get(q); return a && a.length ? a.slice().sort((x, y) => y.i - x.i)[0] : null; };
const cannibal = [...qpMap.entries()]
  .map(([q, a]) => ({ q, total: sum(a, 'i'), pages: a.filter((x) => x.i >= cfg.cannibalMinImpressions).sort((x, y) => x.pos - y.pos) }))
  .filter((x) => x.pages.length >= 2)
  .sort((a, b) => b.total - a.total)
  .map((x) => ({ key: x.q, total: x.total, pages: x.pages.map((p) => ({ path: pathOf(p.page), pos: p.pos, i: p.i, c: p.c })) }));

// ---------- Brand vs non-brand (+ hidden/anonymized) ----------
const brandQ = queries.filter((e) => isBrand(e.key));
const nonBrandQ = queries.filter((e) => !isBrand(e.key));
const agg = (arr) => ({ c: sum(arr, 'c'), i: sum(arr, 'i'), pc: sum(arr, 'pc'), pi: sum(arr, 'pi'), n: arr.filter((e) => e.i > 0).length });
const brandSplit = {
  brand: agg(brandQ),
  nonBrand: agg(nonBrandQ),
  hidden: {
    c: Math.max(0, tc.clicks - sum(queries, 'c')), i: Math.max(0, tc.impressions - sum(queries, 'i')),
    pc: Math.max(0, tp.clicks - sum(queries, 'pc')), pi: Math.max(0, tp.impressions - sum(queries, 'pi'))
  }
};

// ---------- Intent / funnel split ----------
const intentNames = ['Brand', 'Commercial', 'Informational', 'Other / topic'];
const intent = intentNames.map((name) => {
  const arr = queries.filter((e) => intentOf(e.key) === name);
  const a = agg(arr);
  return { name, ...a, examples: arr.filter((e) => e.i > 0).sort((x, y) => y.i - x.i).slice(0, 3).map((e) => e.key) };
});
const visibleImpr = sum(queries, 'i');
const visiblePrevImpr = sum(queries, 'pi');

// ---------- Position buckets (visibility mix) ----------
const bucketNames = ['1-3', '4-10', '11-20', '21-50', '51+'];
const bucketOf = (p) => (p <= 3 ? 0 : p <= 10 ? 1 : p <= 20 ? 2 : p <= 50 ? 3 : 4);
const buckets = bucketNames.map((name) => ({ name, i: 0, n: 0, pi: 0, pn: 0 }));
for (const e of queries) {
  if (e.pos !== null && e.i > 0) { const b = buckets[bucketOf(e.pos)]; b.i += e.i; b.n++; }
  if (e.ppos !== null && e.pi > 0) { const b = buckets[bucketOf(e.ppos)]; b.pi += e.pi; b.pn++; }
}
const deepShare = {
  cur: visibleImpr ? (buckets[3].i + buckets[4].i) / visibleImpr : 0,
  prev: visiblePrevImpr ? (buckets[3].pi + buckets[4].pi) / visiblePrevImpr : 0
};

// ---------- Topic clusters (non-brand) ----------
const STOP = new Set(['a', 'an', 'the', 'in', 'of', 'for', 'to', 'and', 'or', 'vs', 'versus', 'with', 'on', 'is', 'are', 'what', 'how', 'why', 'when', 'which', 'best', 'top', 'use', 'uses', 'using', 'case', 'cases', 'study', 'studies', 'ai', 'software', 'service', 'services', 'solution', 'solutions', 'company', 'companies', 'guide', 'tutorial', 'example', 'examples', 'new', 'free', 'online', 'from', 'by', 'at', 'as', 'it', 'its', 'do', 'does', 'can', 'my', 'your', 'you', 'we', 'vs.']);
const tokensOf = (q) => [...new Set(norm(q).trim().split(' ').filter((t) => t.length > 1 && !STOP.has(t)))];
function buildAssigner() {
  const manual = cfg.topics && Object.keys(cfg.topics).length ? Object.entries(cfg.topics) : null;
  if (manual) {
    return (q) => { const s = norm(q); for (const [name, kws] of manual) if (hasTerm(s, kws)) return name; return null; };
  }
  const w = new Map(), n = new Map();
  for (const e of nonBrandQ) {
    if (e.i <= 0) continue;
    for (const t of tokensOf(e.key)) { w.set(t, (w.get(t) || 0) + e.i); n.set(t, (n.get(t) || 0) + 1); }
  }
  const good = new Set([...n.entries()].filter(([, c]) => c >= 2).map(([t]) => t));
  return (q) => {
    let best = null, bw = -1;
    for (const t of tokensOf(q)) {
      if (!good.has(t)) continue;
      const x = w.get(t);
      if (x > bw || (x === bw && t < best)) { best = t; bw = x; }
    }
    return best;
  };
}
const assign = buildAssigner();
const topicMap = new Map();
for (const e of nonBrandQ) {
  const t = assign(e.key) || '(one-off queries)';
  if (!topicMap.has(t)) topicMap.set(t, { name: t, arr: [] });
  topicMap.get(t).arr.push(e);
}
const topics = [...topicMap.values()].map((t) => ({
  name: t.name, n: t.arr.filter((e) => e.i > 0).length,
  i: sum(t.arr, 'i'), c: sum(t.arr, 'c'), pi: sum(t.arr, 'pi'),
  pos: wpos(t.arr, 'pos', 'i'),
  top: t.arr.filter((e) => e.i > 0).sort((x, y) => y.i - x.i).slice(0, 3).map((e) => e.key)
})).filter((t) => t.i > 0 || t.pi > 0).sort((a, b) => b.i - a.i).slice(0, N);

// ---------- Content sections (URL groups) ----------
const sectionOf = (u) => {
  const segs = pathOf(u).split('/').filter(Boolean);
  return segs.length ? '/' + segs.slice(0, cfg.sectionDepth).join('/') : '/ (home)';
};
const secMap = new Map();
for (const e of pages) {
  const s = sectionOf(e.key);
  if (!secMap.has(s)) secMap.set(s, []);
  secMap.get(s).push(e);
}
const contentSections = [...secMap.entries()].map(([name, arr]) => {
  const i = sum(arr, 'i'), c = sum(arr, 'c');
  return { name, pages: arr.filter((e) => e.i > 0).length, i, c, ctr: i ? c / i : 0, pos: wpos(arr, 'pos', 'i'), pi: sum(arr, 'pi'), pc: sum(arr, 'pc') };
}).filter((s) => s.i > 0 || s.pi > 0).sort((a, b) => b.i - a.i).slice(0, N);

// ---------- Striking distance with estimated upside ----------
const upside = (e) => Math.max(0, e.i * (ctrAt(cfg.targetPosition) - ctrAt(e.pos)));
const strikeAll = nonBrandQ
  .filter((e) => e.pos !== null && e.pos >= cfg.rankingOpportunityMin && e.pos <= cfg.rankingOpportunityMax && e.i >= cfg.opportunityMinImpressions)
  .map((e) => { const pp = primaryPage(e.key); return { ...e, up: upside(e), page: pp ? pathOf(pp.page) : null }; })
  .sort((a, b) => b.up - a.up);
const striking = { rows: strikeAll.slice(0, N), count: strikeAll.length, upside: strikeAll.reduce((s, e) => s + e.up, 0) };

// ---------- Countries ----------
const NAMES = { IND: 'India', USA: 'United States', GBR: 'United Kingdom', CAN: 'Canada', AUS: 'Australia', DEU: 'Germany', FRA: 'France', SGP: 'Singapore', ARE: 'UAE', NLD: 'Netherlands', IRL: 'Ireland', PAK: 'Pakistan', BGD: 'Bangladesh', PHL: 'Philippines', IDN: 'Indonesia', BRA: 'Brazil', SAU: 'Saudi Arabia', ZAF: 'South Africa', CHN: 'China', JPN: 'Japan' };
const cRows = rowsOf('GSC Country Current').map((r) => ({ code: String(r.keys[0]).toUpperCase(), i: r.impressions, c: r.clicks, pos: r.position }));
const cTotal = sum(cRows, 'i');
const countries = cRows.sort((a, b) => b.i - a.i).slice(0, 5).map((r) => ({ ...r, name: NAMES[r.code] || r.code, share: cTotal ? r.i / cTotal : 0 }));
const tgt = (cfg.targetCountries || []).map((x) => x.toUpperCase());
const targetShare = tgt.length && cTotal ? cRows.filter((r) => tgt.includes(r.code)).reduce((s, r) => s + r.i, 0) / cTotal : null;

// ---------- Sections (lists) ----------
const by = (f, dir = -1) => (a, b) => dir * (f(a) - f(b));
const pick = (arr, filt, cmp) => arr.filter(filt).sort(cmp).slice(0, N);
const sections = {
  topClicks: pick(queries, (e) => e.c > 0, by((e) => e.c)),
  topImpressions: pick(queries, (e) => e.i > 0, by((e) => e.i)),
  topRanking: pick(queries, (e) => e.pos !== null && e.pos <= 3 && e.i >= cfg.minImpressions, by((e) => e.c)),
  ctrBelowExpected: pick(queries, (e) => e.pos !== null && e.pos <= cfg.ctrMaxPosition && e.exp >= cfg.ctrMinExpectedClicks && e.c < 0.5 * e.exp, by((e) => e.exp - e.c)),
  improved: pick(queries, (e) => e.status === 'IMPROVED', by((e) => e.posDelta)),
  declined: pick(queries, (e) => e.status === 'DECLINED', by((e) => e.posDelta, 1)),
  newQueries: pick(queries, (e) => e.status === 'NEW', by((e) => e.i)),
  lostQueries: pick(queries, (e) => e.status === 'LOST', by((e) => e.pi)),
  pagesNewWithClicks: pick(pages, (e) => e.pc === 0 && e.c > 0, by((e) => e.c)),
  pagesImproved: pick(pages, (e) => e.status === 'IMPROVED', by((e) => e.posDelta)),
  pagesDeclined: pick(pages, (e) => e.status === 'DECLINED', by((e) => e.posDelta, 1)),
  pagesGainingClicks: pick(pages, (e) => e.pc > 0 && e.clickDiff > 0, by((e) => e.clickDiff)),
  pagesLosingClicks: pick(pages, (e) => e.clickDiff < 0, by((e) => e.clickDiff, 1))
};
sections.ctrBelowExpected.forEach((e) => { e.page = (primaryPage(e.key) || {}).page ? pathOf(primaryPage(e.key).page) : null; });

// ---------- Key takeaways (pure rules, no AI) ----------
const T = [];
const sgn = (x) => (x > 0 ? '+' : '') + x;
const pl = (n, w) => `${n0(n)} ${w}${Math.round(n) === 1 ? '' : 's'}`;
if (kpi.impressions.pct !== null) {
  let t = `Impressions ${sgn(f1(kpi.impressions.pct))}% (${n0(tp.impressions)} → ${n0(tc.impressions)}), clicks ${n0(tp.clicks)} → ${n0(tc.clicks)}.`;
  if (kpi.impressions.pct > 0 && deepShare.cur > deepShare.prev + 0.05) {
    t += ` Growth came mostly from deep rankings: ${Math.round(deepShare.cur * 100)}% of visible-query impressions are now beyond position 20 (was ${Math.round(deepShare.prev * 100)}%). Avg position (${f1(tp.position)} → ${f1(tc.position)}) fell through this mix; individual queries: ${counts.queries.IMPROVED} improved, ${counts.queries.DECLINED} declined.`;
  }
  T.push({ type: kpi.impressions.pct >= 0 ? 'good' : 'warn', text: t });
}
if (tc.clicks > 0) {
  const b = brandSplit.brand, nb = brandSplit.nonBrand, h = brandSplit.hidden;
  T.push({ type: 'info', text: `Brand queries drive ${n0(b.c)} of ${pl(tc.clicks, 'click')}; non-brand queries drive ${pl(nb.c, 'click')} from ${pl(nb.i, 'impression')}. ${pl(h.c, 'click')} (${Math.round((h.c / tc.clicks) * 100)}%) come from anonymized queries that GSC does not list.` });
}
if (topics.length && topics[0].name !== '(one-off queries)') {
  const t = topics[0];
  const where = t.pos > 20 ? 'mostly beyond page 2' : t.pos > 10 ? 'on page 2' : 'on page 1';
  T.push({ type: t.pos > 10 ? 'warn' : 'info', text: `Biggest non-brand topic: "${t.name}" with ${n0(t.i)} impressions over ${pl(t.n, 'query').replace('querys','queries')}, avg position ${f1(t.pos)} (${where}), ${pl(t.c, 'click')}.` });
}
if (striking.count > 0) {
  T.push({ type: 'good', text: `${pl(striking.count, 'non-brand query').replace('querys','queries')} sit at positions ${cfg.rankingOpportunityMin}-${cfg.rankingOpportunityMax}. Reaching position ${cfg.targetPosition} could add roughly ${f1(striking.upside)} clicks per week (estimate from a generic CTR curve, treat as a rough upper bound).` });
}
const com = intent.find((x) => x.name === 'Commercial');
if (visibleImpr > 0) {
  T.push({ type: com.i === 0 ? 'warn' : 'info', text: com.i === 0
    ? 'No commercial-intent queries (services, pricing, case studies, etc.) got impressions: search visibility is brand and informational only.'
    : `Commercial-intent queries are ${Math.round((com.i / visibleImpr) * 100)}% of visible impressions (${n0(com.i)}) and ${pl(com.c, 'click')}.` });
}
if (contentSections.length) {
  const topI = contentSections[0];
  const topC = contentSections.slice().sort((a, b) => b.c - a.c)[0];
  T.push({ type: 'info', text: topC.c > 0 && topC.name !== topI.name
    ? `${topI.name} has the most impressions (${n0(topI.i)}, ${pl(topI.c, 'click')}); ${topC.name} earns the most clicks (${n0(topC.c)}).`
    : `${topI.name} is the most visible section: ${n0(topI.i)} impressions, ${pl(topI.c, 'click')}.` });
}
if (cannibal.length) T.push({ type: 'warn', text: `${pl(cannibal.length, 'query').replace('querys','queries')} served by 2+ of your pages (possible cannibalization), e.g. "${cannibal[0].key}".` });
if (targetShare !== null) T.push({ type: targetShare < 0.5 ? 'warn' : 'info', text: `${Math.round(targetShare * 100)}% of impressions come from your target countries (${tgt.join(', ')}).` });
if (lowVol) T.push({ type: 'warn', text: `Low volume: only ${n0(tc.clicks + tp.clicks)} clicks across both weeks, so treat percentage changes as directional, not conclusive.` });

return [{ json: { kpi, counts, sections, brandSplit, intent, visibleImpr, buckets, deepShare, topics, contentSections, striking, cannibal: cannibal.slice(0, N), countries, targetShare, takeaways: T } }];

const a = $input.first().json;               // Analyze output
const cfg = $('Config').first().json;

// ====== AI SETTINGS ======
const AI = {
  model: 'gemini-3.5-flash',   // AI Studio mein jo free model dikhe, wahi ID daalo (2.5 models 16 Oct 2026 ko band ho rahe hain)
  pageMode: 'growth',          // 'growth' = impressions >= +50% vs last week | 'share' = page has >= 50% of total impressions
  pageThreshold: 0.5,
  minPageImpressions: 10,
  maxCtrQueries: 12,
  maxPages: 6,
  queriesPerPage: 5
};
// =========================

const rowsOf = (name) => $(name).all().flatMap((i) => (i.json && Array.isArray(i.json.rows) ? i.json.rows : []));
const pathOf = (u) => String(u).replace(/^https?:\/\/[^/]+/, '').split('?')[0].split('#')[0] || '/';
const r1 = (x) => Math.round((Number(x) || 0) * 10) / 10;
const brand = (cfg.brandTerms || []).map((t) => t.toLowerCase());
const isBrand = (q) => brand.some((t) => String(q).toLowerCase().includes(t));

// query -> page rows
const qp = rowsOf('GSC QueryPage Current').map((r) => ({ q: r.keys[0], full: r.keys[1], page: pathOf(r.keys[1]), i: r.impressions, c: r.clicks, pos: r.position }));
const primary = new Map();
for (const r of qp) { const b = primary.get(r.q); if (!b || r.i > b.i) primary.set(r.q, r); }

// ---- Group 1: CTR / clicks ----
const seen = new Set();
const ctrQueries = [];
const add = (e, flag) => {
  if (seen.has(e.key) || isBrand(e.key) || ctrQueries.length >= AI.maxCtrQueries) return;
  seen.add(e.key);
  const p = primary.get(e.key);
