html += table('Best ranking queries (position 1-3)', 'Sorted by clicks.', a.sections.topRanking, [{ h: 'Query', f: Q }, cPos, cClicks, cImpr, cCtr]);

// ---------- AI recommendations (Gemini) ----------
html += h2('AI recommendations');
const prioCol = { High: '#dc2626', Medium: '#d97706', Low: '#6b7280' };
const badge = (p) => `<span style="background:${prioCol[p] || '#6b7280'};color:#fff;font-size:11px;padding:2px 7px;border-radius:10px">${esc(p || '')}</span>`;
const ul = (arr) => (arr && arr.length ? '<ul style="margin:4px 0 0 18px;padding:0;font-size:13px;line-height:1.5">' + arr.map((x) => `<li>${esc(x)}</li>`).join('') + '</ul>' : '');
const box = (inner) => `<div style="border:1px solid #e5e7eb;border-radius:8px;padding:10px 14px;margin:8px 0;page-break-inside:avoid">${inner}</div>`;
const sub = (t) => `<div style="font-size:12px;margin-top:6px;color:#374151"><b>${t}</b></div>`;

if (!a.ai || !a.ai.ok) {
  html += `<p style="font-size:13px;color:#9ca3af">AI recommendations were not available this week (${esc((a.ai && a.ai.reason) || 'not run')}).</p>`;
} else {
  html += `<p style="font-size:12px;color:#6b7280">Written by Gemini from the data in this report. Title and meta lines are suggestions only (the live titles were not checked). Verify before applying.</p>`;

  html += h3('Improve CTR / clicks');
  html += a.ai.ctr.length ? a.ai.ctr.map((r) => box(
    `<div><b>${esc(r.query)}</b> ${badge(r.priority)}</div>` +
    `<div style="font-size:12px;color:#6b7280">${esc(r.ref.page || '')} &middot; pos ${f1(r.ref.position)} &middot; ${n0(r.ref.impressions)} impr. &middot; ${n0(r.ref.clicks)} clicks &middot; benchmark ~${f1(r.ref.benchmarkClicks)} clicks${r.extraClicks > 0 ? ` &middot; <b style="color:#16a34a">potential +${f1(r.extraClicks)}/wk</b>` : ''}</div>` +
    `<div style="font-size:13px;margin-top:4px">${esc(r.problem)}</div>` +
    (r.title_options && r.title_options.length ? sub('Title ideas') + ul(r.title_options) : '') +
    (r.meta_option ? sub('Meta idea') + `<div style="font-size:13px">${esc(r.meta_option)}</div>` : '') +
    (r.other_actions && r.other_actions.length ? sub('Other actions') + ul(r.other_actions) : '')
  )).join('') : '<p style="font-size:13px;color:#9ca3af">No CTR recommendations this week.</p>';

  html += h3('Grow impressions on key pages', esc(a.ai.rule || ''));
  html += a.ai.pages.length ? a.ai.pages.map((r) => box(
    `<div><b>${esc(r.page)}</b> ${badge(r.priority)}</div>` +
    `<div style="font-size:12px;color:#6b7280">${n0(r.ref.impressions)} impr. (prev ${n0(r.ref.prevImpressions)}${r.ref.growthPct !== null ? ', ' + pctTxt(r.ref.growthPct) : ''}) &middot; pos ${f1(r.ref.position)} &middot; ${n0(r.ref.clicks)} clicks</div>` +
    `<div style="font-size:13px;margin-top:4px">${esc(r.problem)}</div>` +
    (r.target_queries && r.target_queries.length ? `<div style="font-size:12px;margin-top:6px;color:#374151"><b>Target queries:</b> ${r.target_queries.map(esc).join(', ')}</div>` : '') +
    ul(r.actions)
  )).join('') : '<p style="font-size:13px;color:#9ca3af">No page recommendations this week.</p>';
}

html += `<p style="margin-top:32px;font-size:11px;color:#9ca3af">Source: Google Search Console. All figures are computed with fixed rules; only the "AI recommendations" section is generated by Gemini. Position change = previous minus current (positive = better). Avg position is impression-weighted. GSC hides anonymized queries, so query-level sums are lower than totals. Estimates use a generic CTR benchmark.</p></div>`;

const subject = `SEO Weekly: ${n0(k.clicks.cur)} clicks (${k.lowVol ? signed(k.clicks.cur - k.clicks.prev, 0) : pctTxt(k.clicks.pct, 'n/a')}), ${n0(k.impressions.cur)} impr. | ${cfg.curStart} to ${cfg.curEnd}`;
return [{ json: { subject, html } }];

const { html, subject } = $input.first().json;
const fullHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Weekly SEO Performance Report</title></head><body>${html}</body></html>`;
// Gotenberg needs a real file named exactly index.html
const bin = await this.helpers.prepareBinaryData(Buffer.from(fullHtml, 'utf8'), 'index.html', 'text/html');
return [{ json: { subject }, binary: { data: bin } }];
